text:
Here's your water tracker: tap + for each glass, and it counts toward your goal of 8. It resets itself each new day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; background: #f3f9fc; color: #17324d; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .sub { font-size: 13px; opacity: .7; margin-bottom: 20px; }
  .count { font-size: 56px; font-weight: 700; margin: 8px 0; }
  .bar { height: 14px; background: #d6e6f0; border-radius: 7px; overflow: hidden; max-width: 320px; margin: 0 auto 18px; }
  .fill { height: 100%; width: 0; background: #2f9be0; transition: width .25s; }
  .glasses { font-size: 28px; letter-spacing: 4px; min-height: 40px; margin-bottom: 16px; }
  button { font-size: 18px; border: 0; border-radius: 10px; padding: 10px 22px; margin: 0 6px; background: #2f9be0; color: #fff; cursor: pointer; }
  button.alt { background: #c5d8e6; color: #17324d; }
  .msg { margin-top: 18px; font-size: 14px; min-height: 20px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="sub" id="day"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="glasses" id="icons"></div>
  <button class="alt" id="minus">−</button>
  <button id="plus">+ Glass</button>
  <div class="msg" id="msg"></div>
  <script>
    var GOAL = 8;
    var today = new Date().toDateString();
    var n = 0;
    try {
      if (localStorage.getItem("waterDay") === today) {
        n = parseInt(localStorage.getItem("waterCount"), 10) || 0;
      }
    } catch (e) {}

    function save() {
      try {
        localStorage.setItem("waterDay", today);
        localStorage.setItem("waterCount", String(n));
      } catch (e) {}
    }

    function draw() {
      document.getElementById("day").textContent = today;
      document.getElementById("n").textContent = n;
      document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
      var s = "";
      for (var i = 0; i < Math.max(n, GOAL); i++) { s += i < n ? "💧" : "◌"; }
      document.getElementById("icons").textContent = s;
      document.getElementById("msg").textContent =
        n >= GOAL ? "Goal reached. Nicely done! 🎉" : (GOAL - n) + " more to go.";
    }

    document.getElementById("plus").onclick = function () { n++; save(); draw(); };
    document.getElementById("minus").onclick = function () { if (n > 0) { n--; save(); draw(); } };
    draw();
  </script>
</body>
</html>
```
